module tb_TopModule;
    logic a, b, sel;
    logic out;

    TopModule dut (
        .a(a),
        .b(b),
        .sel(sel),
        .out(out)
    );

    initial begin
        // Test all combinations of a, b, sel
        int errors = 0;
        for (int i = 0; i < 8; i++) {
            {sel, b, a} = i[2:0];
            #1;
            // Expected
            logic expected;
            expected = sel ? b : a;
            if (out !== expected) begin
                $display("FAIL: sel=%b, b=%b, a=%b => out=%b (expected %b)", sel, b, a, out, expected);
                errors++;
            end
        }

        if (errors == 0) begin
            $display("SELFTEST PASS");
        end else begin
            $display("SELFTEST FAIL: %0d errors", errors);
        end
        $finish;
    end
endmodule

module tb_TopModule;
    reg a, b, sel;
    wire out;

    TopModule dut (
        .a(a),
        .b(b),
        .sel(sel),
        .out(out)
    );

    initial begin
        integer errors;
        errors = 0;

        // Test 0
        a = 0; b = 0; sel = 0; #1;
        if (out !== (sel ? b : a)) errors++;

        // Test 1
        a = 1; b = 0; sel = 0; #1;
        if (out !== (sel ? b : a)) errors++;

        // Test 2
        a = 0; b = 1; sel = 0; #1;
        if (out !== (sel ? b : a)) errors++;

        // Test 3
        a = 1; b = 1; sel = 0; #1;
        if (out !== (sel ? b : a)) errors++;

        // Test 4
        a = 0; b = 0; sel = 1; #1;
        if (out !== (sel ? b : a)) errors++;

        // Test 5
        a = 1; b = 0; sel = 1; #1;
        if (out !== (sel ? b : a)) errors++;

        // Test 6
        a = 0; b = 1; sel = 1; #1;
        if (out !== (sel ? b : a)) errors++;

        // Test 7
        a = 1; b = 1; sel = 1; #1;
        if (out !== (sel ? b : a)) errors++;

        if (errors == 0) begin
            $display("SELFTEST PASS");
        end else begin
            $display("SELFTEST FAIL: %0d errors", errors);
        end
        $finish;
    end
endmodule
